          "en": "Call 1330 for tourist interpretation help — directions, lost items, hospitals, and other travel assistance in multiple languages.",
          "ja": "観光通訳案内(1330)は旅行中の言語サポートに使います。道案内・紛失・病院案内など観光関連の通訳が受けられます。"
