          "type": "text",
          "ko": "식용 기념품 1위는 삼양 불닭볶음면(오리지널·카르보·치즈), 농심 짜파게티·너구리·신라면·육개장입니다. 컵라면보다 봉지 멀티팩(5개입)이 마트·다이소에서 저렴합니다.",
