      "jjimTip": "이용 팁\n\n욕탕은 반드시 샤워 후 입수. 큰 소리·뛰어다니기는 금지에 가깝습니다. 귀중품은 본인 락커에, 수면실에서는 짐 관리에 주의하세요. 문신 규정·수영복 규칙은 매장마다 다르니 입구 안내를 확인하세요.",
      "lotteTitle": "롯데월드",
      "lotteDesc": "잠실의 실내·야외 테마파크. 지하철로 바로 갈 수 있어 당일치기에 좋습니다.",
      "lotteBody1": "롯데월드는 잠실 한복판에 있는 실내·야외 복합 테마파크입니다. 날씨가 궂어도 실내에서 놀 수 있고, 롯데월드타워·석촌호수와도 가까워 하루 동선이 잡히기 쉽습니다.",
      "lotteBody2": "보통 온라인·키오스크로 입장권을 사고, 어드벤처(실내)·매직아일랜드(야외)를 자유롭게 이용합니다. 주말·연휴는 줄이 길 수 있으니 인기 어트랙션은 오전에 먼저 도는 편이 좋습니다.",
      "lottePrice": "가격 분위기\n\n당일권은 시즌·프로모션에 따라 달라집니다. 공식 사이트·앱의 당일 할인을 먼저 확인하세요.",
      "lotteTip": "이용 팁\n\n2·8호선 잠실역과 지하·지상으로 연결됩니다. 큰 가방은 물품보관함을 이용하고, 저녁 퍼레이드·야경도 일정에 넣어 보세요.",
      "everlandTitle": "에버랜드",
      "everlandDesc": "용인의 대형 테마파크. 가족·친구와 하루를 보내기 좋은 한국 대표 놀이동산입니다.",
      "everlandBody1": "에버랜드는 경기도 용인에 있는 한국 대표 테마파크입니다. 롤러코스터·사파리·계절 축제까지 넓어서, 하루를 통째로 쓰기 좋은 ‘당일치기 목적 명소’입니다.",
      "everlandBody2": "분당선 죽전·기흥 등에서 에버라인·셔틀·버스로 이동합니다. 개장 직후 인기 라이드를 먼저 타고, 더운 날·비 오는 날은 실내·그늘 동선을 짜 두면 덜 피곤합니다.",
      "everlandPrice": "가격 분위기\n\n온라인 사전 구매가 현장보다 유리한 날이 많습니다. 사파리·일부 체험은 별도일 수 있습니다.",
      "everlandTip": "이용 팁\n\n편한 신발은 필수입니다. 성수기에는 이동·대기 시간이 길어지니, 지도 앱으로 최신 교통을 확인하세요.",
