      "route_amd_s1": "From Incheon Airport T1/T2, follow signs for AREX to the underground platforms. Use elevators if you have a large suitcase.",
      "route_amd_s2": "Buy/ride the All-Stop train (not Express unless you specifically want Seoul Station only). Express is pricier and skips most stops.",
      "route_amd_s3": "Ride to Seoul Station (about 50–60 min). Watch the display for the next stops and get off at Seoul Station.",
