      "route_ahd_cost": "AREX all-stop ~₩4,000",
      "route_ahd_s1": "At Incheon Airport, find the AREX All-Stop platform (both terminals connect to AREX).",
      "route_ahd_s2": "Ride to Hongik Univ. Station — no transfer, one of the easiest first-day routes.",
      "route_ahd_s3": "Move toward the doors when Hongik Univ. appears on the display; stops are short.",
      "route_agn_time": "About 80–110 min",
      "route_agn_cost": "AREX + subway ~₩5,000–6,000",
      "route_agn_s1": "Take AREX All-Stop from the airport. Express only goes to Seoul Station, so All-Stop is usually better for Gangnam.",
      "route_agn_s2": "Recommended: get off at Hongik Univ. → transfer to Line 2 toward Gangnam (check the board for direction).",
