      "route_sgb_cost": "Subway base fare",
      "route_sgb_s1": "Enter Seoul Station subway area (transfers from KTX/AREX can be a long walk).",
      "route_sgb_s2": "Use your map app to Gyeongbokgung Station (Line 3). It will suggest the simplest transfer from Line 1/4.",
      "route_sgb_s3": "Exit 5 is convenient for the palace / Gwanghwamun side — a few minutes on foot.",
      "route_mhd_time": "About 25–40 min",
      "route_mhd_cost": "Subway base fare",
      "route_mhd_s1": "Board at Myeongdong (Line 4). Avoid rush hour if you have big shopping bags.",
      "route_mhd_s2": "Example: Myeongdong → (Line 4) → Dongdaemun History & Culture Park → (Line 2) → Hongik Univ.",
      "route_mhd_s3": "Another option transfers via City Hall to Line 2. Use the map app for the faster option that day.",
      "route_mgn_time": "About 25–40 min",
      "route_mgn_cost": "Subway base fare",
      "route_mgn_s1": "From Myeongdong (Line 4), ride one stop to Chungmuro.",
      "route_mgn_s2": "Transfer to Line 3 (orange signs).",
      "route_mgn_s3": "Ride to Gyodae, transfer to Line 2, then one stop to Gangnam.",
      "route_hit_time": "About 25–40 min",
      "route_hit_cost": "Subway base fare",
      "route_hit_s1": "From Hongik Univ., head toward Gongdeuk (AREX/Line 2 options — check the app).",
      "route_hit_s2": "Transfer at Gongdeuk to Line 6 (brown).",
      "route_hit_s3": "Get off at Itaewon. Exits 1–4 are usually closest to the main street.",
      "tipLabel": "Good to know",
      "route_amd_s4": "Transfer to subway Line 4 (blue). Follow transfer signs; toward Sadang/Namtaeryeong is the Myeongdong direction.",
      "route_amd_s5": "Get off at Myeongdong. Exits 6–8 are often best for the shopping street; confirm the recommended exit in your map app.",
      "route_amd_tip": "Airport buses are an option with very heavy luggage. Keep big bags near the doors/luggage space on AREX.",
      "route_ahd_s4": "Exits 9 and 1 are often closest to the main nightlife streets — check your hotel’s exit number.",
      "route_ahd_s5": "Late at night the area is crowded and alleys are confusing; walking or a short taxi to your stay is fine.",
      "route_ahd_tip": "Hongik Univ. is a big transfer hub (AREX / Line 2 / Gyeongui–Jungang). Wrong exits can add 10+ minutes.",
      "route_agn_s4": "Get off at Gangnam. Exits 11–12 are famous for the main strip, but your hotel may need another exit.",
      "route_agn_s5": "Alternatives: AREX to Seoul Station then bus, or an airport bus with a seat if you have lots of luggage.",
      "route_agn_tip": "Line 2 around Gangnam is very crowded at rush hour. Keep suitcases by the doors, not in the aisle.",
      "route_sgb_s4": "Check closed days (often Mondays) and ticket options before you go.",
      "route_sgb_s5": "Bring a hat/umbrella for heat or rain while walking the grounds.",
      "route_sgb_tip": "Hanbok rental is popular nearby. A small bag makes entry easier.",
      "route_mhd_s4": "At Hongik Univ., pick the exit for Hongdae streets / Yeonnam-dong as needed.",
      "route_mhd_s5": "Evenings are packed — meet friends by exit number.",
      "route_mhd_tip": "It may feel walkable on a map, but the subway is usually faster and easier.",
      "route_mgn_s4": "Exit using the map app’s recommendation for your exact destination.",
      "route_mgn_s5": "Buses work too when traveling light, but subway is clearer for first-timers.",
      "route_mgn_tip": "Chungmuro and Gyodae transfers are relatively short.",
      "route_hit_s4": "Hills and alleys can be tiring with luggage — consider a short taxi at night.",
      "route_hit_s5": "Weekends are crowded; keep valuables in front.",
