          "type": "text",
          "ko": "공항·명동 매장은 관광객용 세트 구성이 많고, 동네 매장은 재고·가격이 다를 수 있습니다.",
          "en": "Airport/Myeongdong stores stock tourist sets; neighborhood stores may differ in stock and price.",
