      "route_hit_s3": "梨泰院駅で降車。メイン通りは1–4番出口が近いことが多いです。",
      "tipLabel": "知っておくと便利",
      "route_amd_s4": "ソウル駅で地下鉄4号線へ乗換。青い4号線案内をたどり、舎堂・南泰嶺方面が明洞方向です。",
      "route_amd_s5": "明洞駅で降車。ショッピング街は6–8番出口が近いことが多いので、地図アプリの推奨出口を確認。",
      "route_amd_tip": "荷物が多い場合は空港バスも選択肢。AREX車内では大きな荷物をドア付近や荷物スペースへ。",
      "route_ahd_s4": "繁華街は9番・1番出口が近いことが多いです。宿の出口番号を確認。",
      "route_ahd_s5": "深夜は混雑し路地も複雑。宿までは徒歩か短いタクシーも安心です。",
      "route_ahd_tip": "弘大入口は大きな乗換駅。出口を間違えると10分以上ロスすることも。",
      "route_agn_s4": "江南駅で降車。11・12番出口が有名ですが、宿により出口が異なります。",
      "route_agn_s5": "代替: ソウル駅までAREX後にバス、または座席のある空港バスも便利です。",
      "route_agn_tip": "通勤時間の2号線江南区間は非常に混みます。大きなキャリーは通路を塞がないように。",
      "route_sgb_s4": "休宮日（月曜など）と入場方法を事前確認。",
      "route_sgb_s5": "暑さや雨に備え帽子・傘があると安心。",
      "route_sgb_tip": "周辺は韓服レンタルが人気。小さめのバッグだと入場が楽です。",
      "route_mhd_s4": "弘大入口で降車後、目的地に合う出口を確認。",
      "route_mhd_s5": "夜は混雑。待ち合わせは出口番号で決めると楽です。",
      "route_mhd_tip": "地図上は近く感じても、地下鉄の方が速いことが多いです。",
      "route_mgn_s4": "地図アプリの推奨出口で降車。",
      "route_mgn_s5": "荷物が少なければバスも可ですが、初めては地下鉄が分かりやすいです。",
      "route_mgn_tip": "忠武路・教大の乗換は比較的短めです。",
      "route_hit_s4": "坂と路地があるので、夜や荷物が多い時は短いタクシーも検討を。",
      "route_hit_s5": "週末夜は混雑。貴重品は前側のバッグへ。",
      "route_hit_tip": "合井乗換ルートもあります。リアルタイムで早い方に従ってください。",
