          "en": "Buying tip\n\nRent for photos; buy small accessories to take home. Full hanbok is bulky and wrinkles in a suitcase.",
          "ja": "買うときのヒント\n\n写真ならレンタル、持ち帰りなら小物が現実的。本格韓服はかさばりしわになりやすいです。"
